R = 10e-6; w = 750e-9; t1 = 0*pi/180; t2 = 90*pi/180; Np = 41;
v = matrix(2*Np, 2);
for(k=1:Np){
  t = t1 + (t2-t1)*(k-1)/(Np-1);
  v(k,1) = (R+w/2)*cos(t); v(k,2) = (R+w/2)*sin(t);
  t = t2 - (t2-t1)*(k-1)/(Np-1);
  v(Np+k,1) = (R-w/2)*cos(t); v(Np+k,2) = (R-w/2)*sin(t);
}
